// ignore_for_file: avoid_print
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:highlight_creator/data/ffi/video_processing_service.dart';

/// Verify that a transition is generated by copying the default template
/// and overlaying the specified description text. Output lands in temp/e2e/.
void main() {
  test('default transition: copy template + overlay "test" text → temp/e2e/', () async {
    // ── Resolve project root (same walking logic as the app) ──────────
    final projectRoot = _resolveProjectRoot();
    final templatePath = '$projectRoot\\app\\windows\\res\\transition.mp4';
    final tempDir = '$projectRoot\\temp\\e2e\\';

    // Enable ffmpeg command logging (project root, survives temp cleanup).
    VideoProcessingService.commandLogPath = '$projectRoot\\ffmpeg_command';
    VideoProcessingService.commandLogContext =
        'default_transition_test.dart :: '
        'default transition: copy template + overlay "test" text \u2192 temp/e2e/';

    // Ensure the template file exists.
    expect(File(templatePath).existsSync(), isTrue,
        reason: 'Template file missing: $templatePath');

    // Ensure temp directory exists.
    final dir = Directory(tempDir);
    if (!dir.existsSync()) await dir.create(recursive: true);

    // Locate ffmpeg.
    final ffmpegPath = await VideoProcessingService.findFfmpeg();
    if (ffmpegPath == null) {
      // Without ffmpeg the service copies the template directly — still valid.
      print('ffmpeg not found — will copy template as-is (simulation mode).');
    }

    final service = VideoProcessingService(ffmpegPath: ffmpegPath);
    final outputPath = '${tempDir}default_transition_test.mp4';

    // ── Generate transition: copy template + add "test" text overlay ──
    final result = await service.generateTransition(
      outputPath: outputPath,
      text: 'test',
      startupVideoPath: '$projectRoot\\test\\e2e\\videoSource\\startup.mp4',
      transitionTemplatePath: templatePath,
    );

    expect(result.exitCode, 0,
        reason: 'ffmpeg failed:\n${result.stderr}');

    // ── Verify output ─────────────────────────────────────────────────
    final outFile = File(outputPath);
    expect(outFile.existsSync(), isTrue,
        reason: 'Output file was not created: $outputPath');

    final size = outFile.lengthSync();
    print('Output: $outputPath  (${(size / 1024).toStringAsFixed(1)} KB)');
    expect(size, greaterThan(1000),
        reason: 'Output file too small — likely corrupt');
  });

  test('Chinese transition: overlay Chinese description text → temp/e2e/', () async {
    final projectRoot = _resolveProjectRoot();
    final templatePath = '$projectRoot\\app\\windows\\res\\transition.mp4';
    final tempDir = '$projectRoot\\temp\\e2e\\';

    VideoProcessingService.commandLogContext =
        'default_transition_test.dart :: '
        'Chinese transition: overlay Chinese description text';

    expect(File(templatePath).existsSync(), isTrue,
        reason: 'Template file missing: $templatePath');

    final dir = Directory(tempDir);
    if (!dir.existsSync()) await dir.create(recursive: true);

    final ffmpegPath = await VideoProcessingService.findFfmpeg();
    final service = VideoProcessingService(ffmpegPath: ffmpegPath);
    final outputPath = '${tempDir}chinese_transition_test.mp4';

    const chineseText = '精彩回放';

    final result = await service.generateTransition(
      outputPath: outputPath,
      text: chineseText,
      startupVideoPath: '$projectRoot\\test\\e2e\\videoSource\\startup.mp4',
      transitionTemplatePath: templatePath,
    );

    expect(result.exitCode, 0,
        reason: 'ffmpeg failed:\n${result.stderr}');

    final outFile = File(outputPath);
    expect(outFile.existsSync(), isTrue,
        reason: 'Output file was not created: $outputPath');

    final size = outFile.lengthSync();
    print('Output: $outputPath  (${(size / 1024).toStringAsFixed(1)} KB)');
    expect(size, greaterThan(1000),
        reason: 'Output file too small — likely corrupt');
  });
}

/// Walk up from cwd to find the project root (AGENTS.md or app/ dir).
String _resolveProjectRoot() {
  var dir = Directory.current;
  while (true) {
    if (File('${dir.path}\\AGENTS.md').existsSync() ||
        Directory('${dir.path}\\app').existsSync()) {
      return dir.path;
    }
    final parent = dir.parent;
    if (parent.path == dir.path) break;
    dir = parent;
  }
  return Directory.current.path;
}